+  git(root, "clone", "--depth=1", "--branch", "main", `file://${remote}`, work);
+  git(work, "config", "user.name", "Atomaton Test");
+  git(work, "config", "user.email", "atomaton@example.com");
+  return { root, seed, work };
+}
